description:
Implement `useStorageSync` — a hook that syncs state with `localStorage` and listens for `storage` events to update across browser tabs.

**Example:**
```tsx
const [theme, setTheme] = useStorageSync('theme', 'light');
// Changing theme in one tab updates all other tabs
```

starter_code:
import { useState, useEffect, useCallback } from 'react';

export function useStorageSync<T>(key: string, initial: T): [T, (v: T) => void] {
  // your code here
}

test_suite:
beforeEach(() => localStorage.clear());

test('returns initial value when key not in storage', () => {
  const [value] = renderHook(() => useStorageSync('color', 'blue')).result.current;
  expect(value).toBe('blue');
});

test('reads existing value from localStorage', () => {
  localStorage.setItem('color', JSON.stringify('red'));
  const [value] = renderHook(() => useStorageSync('color', 'blue')).result.current;
  expect(value).toBe('red');
});

test('setter updates state and localStorage', () => {
  const { result } = renderHook(() => useStorageSync('count', 0));
  act(() => result.current[1](5));
  expect(result.current[0]).toBe(5);
  expect(JSON.parse(localStorage.getItem('count')!)).toBe(5);
});

test('updates when storage event fires with matching key', () => {
  const { result } = renderHook(() => useStorageSync('theme', 'light'));
  act(() => {
    window.dispatchEvent(new StorageEvent('storage', {
      key: 'theme',
      newValue: JSON.stringify('dark'),
    }));
  });
  expect(result.current[0]).toBe('dark');
});

// __hidden__
test('ignores storage event for different key', () => {
  const { result } = renderHook(() => useStorageSync('theme', 'light'));
  act(() => {
    window.dispatchEvent(new StorageEvent('storage', {
      key: 'other-key',
      newValue: JSON.stringify('dark'),
    }));
  });
  expect(result.current[0]).toBe('light');
});

solution:
import { useState, useEffect, useCallback } from 'react';

export function useStorageSync<T>(key: string, initial: T): [T, (v: T) => void] {
  const [value, setValue] = useState<T>(() => {
    try {
      const item = localStorage.getItem(key);
      return item !== null ? JSON.parse(item) : initial;
    } catch {
      return initial;
    }
  });

  useEffect(() => {
    const handler = (e: StorageEvent) => {
      if (e.key !== key) return;
      try {
        setValue(e.newValue !== null ? JSON.parse(e.newValue) : initial);
      } catch {
        setValue(initial);
      }
    };
    window.addEventListener('storage', handler);
    return () => window.removeEventListener('storage', handler);
  }, [key, initial]);

  const set = useCallback((v: T) => {
    setValue(v);
    localStorage.setItem(key, JSON.stringify(v));
  }, [key]);

  return [value, set];
}
